/* JSZip loader (repo-mode). */
(function () {
  if (window.JSZip) {
    return;
  }
  var script = document.createElement("script");
  script.src = "../extension/lib/jszip.min.js";
  script.onload = function () {
    if (!window.JSZip) {
      console.error("JSZip failed to load from local path.");
    }
  };
  script.onerror = function () {
    console.error("JSZip loader failed. Bundle JSZip for standalone use.");
  };
  document.head.appendChild(script);
})();
